const bodyData = $json.body?.data || {};
const key = bodyData.key || {};

const remoteJid = String(key.remoteJid || '');
const isFromMe = key.fromMe === true;
const source = String(bodyData.source || '').trim().toLowerCase();

const messageType = bodyData.messageType || $json.body?.messages?.records?.[0]?.messageType || '';
const messageText = String(
  bodyData.message?.conversation ||
  bodyData.message?.extendedTextMessage?.text ||
  ''
).trim();

const phone = remoteJid.endsWith('@s.whatsapp.net')
  ? remoteJid.replace(/[^0-9]/g, '')
  : '';

const isTextMessage = Boolean(messageText);
const isStatus = remoteJid.endsWith('@status');

// Les messages ecrits manuellement depuis le telephone du compte
// connecte a Evolution API remontent avec fromMe=true et source=android.
const isManualMessageFromOwner = isFromMe === true && source === 'android';

return [{
  json: {
    phone,
    remoteJid,
    isFromMe,
    source,
    participant: String(key.participant || ''),
    addressingMode: String(key.addressingMode || ''),
    pushName: String(bodyData.pushName || ''),
    messageType,
    messageText,
    isTextMessage,
    isStatus,
    isManualMessageFromOwner,
    processMessage: Boolean(remoteJid) && isTextMessage && !isStatus,
    body: $json.body
  }
}];

const inbound = $('Préparation & Normalisation').first().json;
const rows = $input.all().map(item => item.json || {});

const groupRow = rows.find(row =>
  String(row.group_name || '').trim() === 'MyBot DST1' &&
  String(row.remoteJid || '').trim().endsWith('@g.us')
);

const botGroupJid = String(groupRow?.remoteJid || '').trim();
const isBotGroup = Boolean(botGroupJid) && inbound.remoteJid === botGroupJid;
const isPrivateChat = inbound.remoteJid.endsWith('@s.whatsapp.net');

// Accepte :
// - messages d'un autre membre du groupe ;
// - messages ecrits depuis le telephone Android du proprietaire.
// Ignore les messages issus d'Evolution API afin d'eviter les boucles.
const isAllowedBotCommand = isBotGroup && (
  inbound.isFromMe === false ||
  inbound.isManualMessageFromOwner === true
);

// Les reponses automatiques sont reservees aux messages prives entrants.
const isAllowedPrivateAutoReply = isPrivateChat && inbound.isFromMe === false;

let route = 'ignore';

if (isAllowedBotCommand) {
  route = 'dst1';
} else if (isAllowedPrivateAutoReply) {
  route = 'auto_reply';
}

return [{
  json: {
    ...inbound,
    botGroupJid,
    isBotGroup,
    isPrivateChat,
    isAllowedBotCommand,
    isAllowedPrivateAutoReply,
    route
  }
}];

const request = $('Déterminer le routage').first().json;

const actions = Array.isArray($json.actions_effectuees)
  ? $json.actions_effectuees
  : [];

// Cas 1 : DST1 retourne une erreur structuree, HTTP 200.
// Cas 2 : le node HTTP n8n continue apres une erreur HTTP / reseau.
const endpointError = String(
  $json.error ||
  $json.errorMessage ||
  $json.message ||
  ''
).trim();

let rawResponseText = String($json.reponse_texte || '').trim();

if (endpointError && !rawResponseText) {
  rawResponseText =
    "Je n'ai pas pu traiter cette demande a cause d'un probleme technique. " +
    "Reessaie dans quelques instants.";
}

// Evite que des asterisques produits par le LLM cassent le gras WhatsApp.
const responseText = rawResponseText.replace(/\*/g, '').trim();

const hasToolError = Boolean(endpointError) || actions.some(action => {
  const result = action?.resultat;

  return Boolean(
    result &&
    typeof result === 'object' &&
    (result.error || result.success === false)
  );
});

const hasSuccessfulToolAction = actions.some(action => {
  const result = action?.resultat;

  return Boolean(
    result &&
    typeof result === 'object' &&
    result.success === true
  );
});

const normalizedText = responseText.toLowerCase();

// Version volontairement sur une seule regex, sans flag /x :
// compatible avec le JavaScript execute par le node Code n8n.
const isClarification = !hasToolError && (
  responseText.endsWith('?') ||
  /\b(pour quel|pour quelle|quel contact|quelle personne|quel numero|quelle date|quelle heure|peux-tu preciser|peux tu preciser|j ai besoin de|il me faut|de quel|duquel|laquelle)\b/.test(normalizedText)
);

let icon = '🤖';
let responseType = 'information';

if (hasToolError) {
  icon = '❌';
  responseType = 'echec';
} else if (isClarification) {
  icon = '❓';
  responseType = 'clarification';
} else if (hasSuccessfulToolAction) {
  icon = '✅';
  responseType = 'succes';
}

const formattedResponseText = responseText
  ? `${icon} *${responseText}*`
  : '❌ *DST1 n a renvoye aucune reponse exploitable.*';

return [{
  json: {
    recipient: request.remoteJid,
    responseText,
    formattedResponseText,
    responseIcon: icon,
    responseType,
    shouldReply: true,
    sessionId: String($json.session_id || ''),
    endpointError: endpointError || null,
    actionsCount: actions.length
  }
}];
